test('F-038 B-L4: Progress uses tokens and explicit transition properties; Spin tip, reduced-motion (slow, not stop) and mask are tokenized', () => {
  const bg = rule('.joy-progress__bg');
  assert.doesNotMatch(bg, /transition:\s*all/, 'no transition: all');
  assert.match(bg, /transition:\s*width /);
  assert.match(bg, /background-color:\s*var\(--joy-accent-text\)/, 'default fill is accent-text (accent-default is 2.16:1 on the light track)');
  assert.match(rule('.joy-progress__inner'), /background-color:\s*var\(--joy-surface-sunken\)/);
  assert.match(rule('.joy-progress--status-success .joy-progress__bg'), /var\(--joy-status-success-fg\)/);
  assert.match(rule('.joy-progress--status-exception .joy-progress__bg'), /var\(--joy-status-danger-fg\)/);
  assert.match(rule('.joy-spin__tip'), /color:\s*var\(--joy-accent-text\)/);
  const mask = rule('.joy-spin__mask');
  assert.doesNotMatch(mask, /backdrop-filter/, 'no glassmorphism blur on the spin mask');
  assert.match(mask, /background-color:\s*color-mix\(in srgb, var\(--joy-surface-overlay\) 70%, transparent\)/);
  // The global reduced-motion block forces 0.01ms / 1 iteration with !important, which would stop the
  // spinner. The Spin override must therefore be !important, more specific, and after the base rule.
  const base = css.indexOf('\n.joy-spin__indicator {');
  const reduced = css.search(/@media \(prefers-reduced-motion: reduce\) \{\s*\.joy-spin \.joy-spin__indicator \{/);
  assert.ok(base !== -1 && reduced > base, 'spin reduced-motion block follows the base rule');
  const block = css.slice(reduced, reduced + 260);
  assert.match(block, /animation-duration:\s*4s !important/);
  assert.match(block, /animation-iteration-count:\s*infinite !important/);
  assert.doesNotMatch(css.slice(css.indexOf('\n.joy-spin {'), css.indexOf('\n.joy-spin__container')), /#[0-9a-fA-F]{3,8}\b|brand-primary/);
});

test('F-038 B-L4 fix: Progress fills reach >= 3:1 (WCAG 1.4.11) against the track in both themes', () => {
  const grab = (re) => {
    const v = {};
    for (const m of css.matchAll(re)) {
      for (const l of m[1].split(';')) {
        const x = l.match(/(--[\w-]+)\s*:\s*(.+)/);
        if (x) v[x[1]] = x[2].trim();
      }
    }
    return v;
  };
  const light = grab(/:root\s*\{([^}]+)\}/g);
  const dark = { ...light, ...grab(/\[data-theme="dark"\]\s*\{([^}]+)\}/g) };
  const resolve = (val, store, depth = 0) => {
    const m = val && val.match(/^var\((--[\w-]+)\)$/);
    return m && depth < 10 ? resolve(store[m[1]], store, depth + 1) : val;
  };
  const tokenOf = (sel, prop) => {
    const m = css.match(new RegExp(`\\n${sel.replace(/[.]/g, '\\.')} \\{([^}]*)\\}`));
    assert.ok(m, `${sel} rule exists`);
    const d = m[1].match(new RegExp(`${prop}:\\s*var\\((--[\\w-]+)\\)`));
    assert.ok(d, `${sel} ${prop} is a token`);
    return d[1];
  };
  const trackTok = tokenOf('.joy-progress__inner', 'background-color');
  const fills = {
    default: tokenOf('.joy-progress__bg', 'background-color'),
    success: tokenOf('.joy-progress--status-success .joy-progress__bg', 'background-color'),
    exception: tokenOf('.joy-progress--status-exception .joy-progress__bg', 'background-color'),
  };
  for (const [theme, store] of [['light', light], ['dark', dark]]) {
    const track = resolve(store[trackTok], store);
    for (const [name, tok] of Object.entries(fills)) {
      const ratio = contrastRatio(resolve(store[tok], store), track);
      assert.ok(ratio >= 3, `${theme}: ${name} fill ${tok} vs track ${trackTok} is ${ratio.toFixed(2)}:1 (< 3:1)`);
    }
  }
});

// ---- F-038 B-L5: Anchor, Breadcrumb, Menu, Pagination, Steps, Tabs ----
const B5_SELECTORS = ['.joy-anchor', '.joy-anchor__ink', '.joy-anchor__ink-ball', '.joy-anchor__link', '.joy-breadcrumb', '.joy-breadcrumb__link', '.joy-breadcrumb__current', '.joy-breadcrumb__sep', '.joy-menu', '.joy-menu__item', '.joy-pagination', '.joy-pagination__btn', '.joy-pagination__ellipsis', '.joy-steps', '.joy-steps__item', '.joy-steps__icon', '.joy-tabs', '.joy-tab-btn'];
/** Every top-level rule (incl. @media-nested) whose selector list mentions one of this lane's component prefixes. */
const b5Rules = () => {
  const out = [];
  const noComments = css.replace(/\/\*[\s\S]*?\*\//g, '');
  for (const m of noComments.matchAll(/(^|\n)\s*([^{}@\n][^{}]*?)\s*\{([^{}]*)\}/g)) {
    if (/\.joy-(anchor|breadcrumb|menu|pagination|steps|tabs?)(-|_|\b)/.test(m[2])) out.push({ sel: m[2].trim(), body: m[3] });
  }
  return out;
};
/** Body of every `@media (pointer: coarse)` block, concatenated. */
const coarse = () => [...css.matchAll(/@media \(pointer: coarse\) \{([\s\S]*?)\n\}\n/g)].map((m) => m[1]).join('\n');

test('F-038 B-L5: no foreign hex, purple or slate fallback and no >1px side stripe in Anchor/Breadcrumb/Menu/Pagination/Steps/Tabs rules', () => {
  const rules = b5Rules();
  assert.ok(rules.length >= 40, `found the lane rules (${rules.length})`);
  for (const { sel, body } of rules) {
    assert.doesNotMatch(body, /#[0-9a-fA-F]{3,8}\b|rgba?\(|hsla?\(/, `${sel} has a colour literal`);
    assert.doesNotMatch(body, /brand-primary|--joy-color-|--gold-|--navy-/, `${sel} references a legacy/ramp token`);
    assert.doesNotMatch(body, /border-(left|right)\s*:\s*([2-9]|\d\d)/, `${sel} has a side stripe`);
    assert.doesNotMatch(body, /transition:\s*all\b/, `${sel} uses transition: all`);
  }
  for (const sel of B5_SELECTORS) assert.ok(rules.some((r) => r.sel.split(',').map((x) => x.trim()).includes(sel)), `${sel} rule exists`);
  const inline = css.match(/\.joy-menu--inline \.joy-menu__item--active \{([^}]*)\}/);
  assert.ok(!inline || !/border-right/.test(inline[1]), 'inline active menu item has no border-right stripe');
});

test('F-038 B-L5: Anchor, Breadcrumb, Menu, Pagination, Steps and Tabs reach 44px on coarse pointers', () => {
  const c = coarse();
  const has = (sel, re) => assert.match(c, new RegExp(`${sel.replace(/[.]/g, '\\.')}\\s*\\{[^}]*${re}`), `${sel} ${re} under (pointer: coarse)`);
  has('.joy-anchor__link', 'min-height:\\s*44px');
  has('.joy-breadcrumb__link', 'min-height:\\s*44px');
  has('.joy-menu__item', 'min-height:\\s*44px');
  has('.joy-pagination__btn', 'min-width:\\s*44px');
  has('.joy-pagination__btn', 'min-height:\\s*44px');
  has('.joy-tab-btn', 'min-height:\\s*44px');
  has('.joy-steps__item', 'min-height:\\s*44px');
  assert.match(rule('.joy-pagination__btn'), /height:\s*32px/, 'desktop keeps the compact 32px button');
});

